from collections import deque

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        ropes = []
        for _ in range(n):
            a, b = map(int, input().split())
            ropes.append((a, b))
        ropes.sort(key=lambda x: x[0])
        queue = deque()
        for i in range(n):
            if ropes[i][0] == 0:
                queue.append(i)
        count = 0
        while queue:
            index = queue.popleft()
            if index + 1 < n and ropes[index + 1][0] <= ropes[index][0] + ropes[index][1]:
                queue.append(index + 1)
            else:
                count += 1
        print(count)

