        for opinion in member_counts:
            if opinion == '+':
                y += member_counts[opinion]
            else:
                n += member_counts[opinion]
        if y > n:
            members = [member for member in members if member.count('-') == 0]
        elif y < n:
            members = [member for member in members if member.count('+') == 0]
        else:
            members = []
        max_members = max(max_members, len(members))
    print(max_members)

