def solve():
    a, b = map(int, input().split())
    n, m = map(int, input().split())

    min_price = min(a, b)
    max_price = max(a, b)

    result = n
    if m >= n:
        result = min_price * n
    else:
        result = min_price * m + max_price * (n - m)
        for i in range(1, n):
            if i + 1 <= m:
                result = min(result, min_price * i + max_price * (n - i))
            else:
                break

    print(result)

